import Foundation

/// Stable destinations for the Help menu and contextual troubleshooting links.
public enum HelpTopicID: String, CaseIterable, Sendable {
    case gettingStarted, repositoryList, stagingAndCommit, history, branchesAndWorktrees
    case conflicts, syncAndUndo, stashes, reviews, reviewTroubleshooting
    case commandRunner, settings, keyboard, troubleshooting, refreshTroubleshooting
    case gitTroubleshooting, installation, safety
}

public enum HelpCategory: String, CaseIterable, Sendable {
    case start = "Getting Started"
    case git = "Working with Git"
    case reviews = "Code Reviews"
    case tools = "Tools and Preferences"
    case troubleshooting = "Troubleshooting"
}

public struct HelpSection: Sendable {
    public let title: String
    public let paragraphs: [String]
    public let steps: [String]

    init(_ title: String, _ paragraphs: [String] = [], steps: [String] = []) {
        self.title = title
        self.paragraphs = paragraphs
        self.steps = steps
    }
}

public struct HelpArticle: Identifiable, Sendable {
    public let id: HelpTopicID
    public let category: HelpCategory
    public let title: String
    public let summary: String
    public let symbol: String
    public let keywords: [String]
    public let sections: [HelpSection]
    public let related: [HelpTopicID]
}

/// Compiled into the app so Help remains available offline and in copied builds.
public enum HelpContent {
    public static func article(_ id: HelpTopicID) -> HelpArticle? {
        articles.first { $0.id == id }
    }

    /// Every query term must match. Titles and aliases rank above body matches;
    /// ties keep the curated article order. Punctuation and accents are ignored.
    public static func search(_ query: String) -> [HelpArticle] {
        let terms = normalized(query).split(separator: " ").map(String.init)
        guard !terms.isEmpty else { return articles }
        return articles.enumerated().compactMap { index, article -> (Int, Int, HelpArticle)? in
            let title = normalized(article.title)
            let aliases = normalized(article.keywords.joined(separator: " "))
            let summary = normalized(article.summary)
            let body = normalized(article.sections.flatMap { [$0.title] + $0.paragraphs + $0.steps }.joined(separator: " "))
            let fields = [title, aliases, summary, body]
            guard terms.allSatisfy({ term in fields.contains { $0.contains(term) } }) else { return nil }
            let score = terms.reduce(0) { score, term in
                score + (title.contains(term) ? 12 : aliases.contains(term) ? 8 : summary.contains(term) ? 4 : 1)
            } + (title == terms.joined(separator: " ") ? 30 : 0)
            return (score, index, article)
        }.sorted { lhs, rhs in
            lhs.0 == rhs.0 ? lhs.1 < rhs.1 : lhs.0 > rhs.0
        }.map { $0.2 }
    }

    private static func normalized(_ text: String) -> String {
        text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
            .split(whereSeparator: { !$0.isLetter && !$0.isNumber }).joined(separator: " ")
    }

